#!/usr/bin/env python3
# GENERATED by plugin-cursor/scripts/compose.sh — edit plugin-claude/ then re-compose
"""
Sprint capacity validator for synaptory.

Validates that a sprint's total human review hours do not exceed the
configured capacity threshold (default: 80% of available hours).

Usage:
  python3 sprint_capacity.py --project-dir . --sprint 1
  python3 sprint_capacity.py --project-dir . --sprint all

Exit codes:
  0 = OK (within capacity)
  1 = OVERLOADED (exceeds threshold)
  2 = ERROR (missing data or config)
"""

import argparse
import json
import subprocess
import sys
import os


# Story size → estimated human review hours
REVIEW_HOURS = {
    "XS": 0.5,
    "S":  1.0,
    "M":  2.0,
    "L":  4.0,
    "XL": 8.0,
}


def get_tracker_cli(project_dir):
    plugin_root = os.environ.get("PLUGIN_ROOT", "")
    if plugin_root:
        return f"python3 {plugin_root}/skills/_shared/scripts/tracker/tracker_cli.py --project-dir {project_dir}"
    # Fallback: assume tracker_cli.py is in the same directory
    script_dir = os.path.dirname(os.path.abspath(__file__))
    return f"python3 {script_dir}/tracker/tracker_cli.py --project-dir {project_dir}"


def run_tracker(tracker_cli, command):
    full_cmd = f"{tracker_cli} {command}"
    result = subprocess.run(full_cmd, shell=True, capture_output=True, text=True)
    if result.returncode != 0:
        raise RuntimeError(f"tracker_cli failed: {result.stderr.strip()}")
    return result.stdout.strip()


def validate_sprint(tracker_cli, sprint_num, reviewer_count, review_hours_per_week, capacity_percent):
    """Validate capacity for a single sprint. Returns result dict."""
    try:
        raw = run_tracker(tracker_cli, f"get-sprint-backlog {sprint_num}")
    except RuntimeError as e:
        return {
            "sprint": sprint_num,
            "status": "ERROR",
            "error": str(e),
            "sprint_total_hours": 0,
            "available_capacity": 0,
            "utilization_percent": 0,
            "stories": [],
        }

    try:
        stories_raw = json.loads(raw) if raw else []
    except json.JSONDecodeError:
        # tracker may return markdown or non-JSON — treat as empty
        stories_raw = []

    available_capacity = reviewer_count * review_hours_per_week * (capacity_percent / 100.0)

    stories = []
    for story in stories_raw:
        size = story.get("size", "M").upper()
        review_hrs = REVIEW_HOURS.get(size, REVIEW_HOURS["M"])
        stories.append({
            "id": story.get("id", "unknown"),
            "title": story.get("title", ""),
            "size": size,
            "review_hours": review_hrs,
        })

    stories.sort(key=lambda s: s["review_hours"], reverse=True)
    sprint_total = sum(s["review_hours"] for s in stories)
    utilization = (sprint_total / available_capacity * 100) if available_capacity > 0 else 0

    if utilization > 100:
        status = "OVERLOADED"
    elif utilization < 40:
        status = "UNDERLOADED"
    else:
        status = "OK"

    return {
        "sprint": sprint_num,
        "status": status,
        "sprint_total_hours": round(sprint_total, 1),
        "available_capacity": round(available_capacity, 1),
        "utilization_percent": round(utilization, 1),
        "reviewer_count": reviewer_count,
        "review_hours_per_week": review_hours_per_week,
        "capacity_percent": capacity_percent,
        "stories": stories,
    }


def main():
    parser = argparse.ArgumentParser(description="Validate sprint review capacity")
    parser.add_argument("--project-dir", required=True, help="Project root directory")
    parser.add_argument("--sprint", required=True, help="Sprint number (integer) or 'all'")
    parser.add_argument("--reviewer-count", type=int, default=2, help="Number of reviewers (default: 2)")
    parser.add_argument("--review-hours-per-week", type=float, default=15.0,
                        help="Combined review hours per week across all reviewers (default: 15)")
    parser.add_argument("--capacity-percent", type=float, default=80.0,
                        help="Capacity threshold percentage (default: 80)")
    args = parser.parse_args()

    tracker_cli = get_tracker_cli(args.project_dir)

    if args.sprint.lower() == "all":
        # Get all sprint numbers from tracker
        try:
            raw = run_tracker(tracker_cli, "list-sprints")
            sprints_data = json.loads(raw) if raw else []
            sprint_nums = [s.get("number") for s in sprints_data if s.get("number")]
        except (RuntimeError, json.JSONDecodeError):
            sprint_nums = []

        if not sprint_nums:
            print(json.dumps({"error": "No sprints found in tracker", "status": "ERROR"}))
            sys.exit(2)

        results = []
        any_overloaded = False
        for num in sprint_nums:
            r = validate_sprint(tracker_cli, num, args.reviewer_count,
                                args.review_hours_per_week, args.capacity_percent)
            results.append(r)
            if r["status"] == "OVERLOADED":
                any_overloaded = True

        print(json.dumps(results, indent=2))
        sys.exit(1 if any_overloaded else 0)

    else:
        try:
            sprint_num = int(args.sprint)
        except ValueError:
            print(json.dumps({"error": f"Invalid sprint number: {args.sprint}", "status": "ERROR"}))
            sys.exit(2)

        result = validate_sprint(tracker_cli, sprint_num, args.reviewer_count,
                                 args.review_hours_per_week, args.capacity_percent)
        print(json.dumps(result, indent=2))
        sys.exit(1 if result["status"] == "OVERLOADED" else 0)


if __name__ == "__main__":
    main()
